if($configExists&&$pdoMysql){try{$cfg=require $configFile;$d=$cfg['db']??[];$dsn=sprintf('mysql:host=%s;dbname=%s;charset=%s',$d['host']??'localhost',$d['name']??'',$d['charset']??'utf8mb4');$check=new PDO($dsn,$d['user']??'',$d['pass']??'',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);$dbOk=true;$dbMessage='Подключение OK';$need=['users','wallet_transactions','user_game_states','game_rounds'];$found=$check->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);$diff=array_diff($need,$found);$tablesOk=!$diff;$tableMessage=$tablesOk?'Все найдены':'Отсутствуют: '.implode(', ',$diff);if(is_file(__DIR__.'/app/migrations.php')){require_once __DIR__.'/app/migrations.php';$known=array_keys(cc_migrations());$hasMigrationTable=in_array('schema_migrations',$found,true);$applied=[];if($hasMigrationTable)$applied=array_map('strval',$check->query('SELECT version FROM schema_migrations')->fetchAll(PDO::FETCH_COLUMN));$pending=array_values(array_diff($known,$applied));$migrationsOk=$hasMigrationTable&&!$pending;$migrationMessage=$migrationsOk?'Актуальны':($hasMigrationTable?'Ожидают: '.implode(', ',$pending):'Нужно выполнить tools/migrate.php');}}catch(Throwable $e){$dbMessage='Ошибка подключения';$tableMessage='Недоступно';$migrationMessage='Недоступно';}}
